## Submitted testbench
```systemverilog
module tb;

  // -------------------------------------------------
  // Clock and reset
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;               // 125 MHz
  logic clk = 1'b0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst = 1'b1;

  // -------------------------------------------------
  // DUT ports
  // -------------------------------------------------
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic [15:0] prescale = 16'd5;             // default prescale

  // AXI sink (always ready)
  assign s_axis_tready = 1'b1;               // ignore handshake for stimulus

  // Receiver side signals
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready = 1'b1;          // always ready
  logic       rxd = 1'b1;
  logic       txd;
  logic       tx_busy;
  logic       rx_busy;
  logic       rx_overrun_error;
  logic       rx_frame_error;

  // -------------------------------------------------
  // Instantiate the design (default parameters)
  // -------------------------------------------------
  uart dut (
    .clk               (clk),
    .rst               (rst),
    .s_axis_tdata      (s_axis_tdata),
    .s_axis_tvalid     (s_axis_tvalid),
    .s_axis_tready     (),                 // unused output, leave unconnected
    .txd               (txd),
    .rxd               (rxd),
    .tx_busy           (tx_busy),
    .rx_busy           (rx_busy),
    .rx_overrun_error  (rx_overrun_error),
    .rx_frame_error    (rx_frame_error),
    .prescale          (prescale)
  );

  // -------------------------------------------------
  // Reset sequence
  // -------------------------------------------------
  initial begin
    #1 rst = 1'b0;               // deassert reset after a few cycles
    #(CLK_PERIOD*2);
    rst = 1'b1;
    #(CLK_PERIOD*2);
    rst = 1'b0;
    #(CLK_PERIOD*2);
  end

  // -------------------------------------------------
  // Create a frame error, then idle for ≥16 clocks
  // -------------------------------------------------
  initial begin
    // Wait until reset is released
    @(negedge rst);
    #1;

    // Drive a start condition (rxd low) and hold it long enough to
    // cause a frame_error (stop bit held low)
    rxd = 1'b0;                                   // start bit
    #10000;                                      // enough cycles for start detection
    // Keep rxd low continuously to force a bad stop bit → frame_error
    // (no further action needed – the DUT will assert frame_error)

    // Wait for the error to be processed and busy to go low
    wait (!rx_busy);                              // idle when busy is low

    // Release rxd and keep it high for at least 16 clocks while busy stays low
    rxd = 1'b1;
    repeat (20) @(posedge clk);                  // idle period ≥16 clocks

    // -------------------------------------------------
    // Deliver a fresh frame that contains 8'hA5
    // -------------------------------------------------
    s_axis_tvalid = 1'b1;
    s_axis_tdata  = 8'hA5;

    // Give the DUT enough time to serialize the byte and present it on the AXI output
    #10000;                                      // sufficient for one frame transmission

    $finish;                                     // clean termination
  end

endmodule
```

